try {
    int x = 10 / 0;
} catch (ArithmeticException ex) {
    System.out.println("caught");
}

public static int test() {
    try {
        System.out.println("try");
        return 10;
    } finally {
        System.out.println("finally");
    }
}
public static void main(String[] args) {
    System.out.println(test());
}

public static int test() {
    try {
        return 10;
    } finally {
        return 20;
    }
}
public static void main(String[] args) {
    System.out.println(test());
}

try {
    throw new java.io.FileNotFoundException();
} catch (java.io.FileNotFoundException | java.io.IOException e) {
    System.out.println("caught");
}

static class Door implements AutoCloseable {
    String name;
    Door(String n) { name = n; }
    public void close() { System.out.print(name + " "); }
}
public static void main(String[] args) {
    try (Door d1 = new Door("A"); Door d2 = new Door("B")) {
        System.out.print("try ");
    }
}

public static void main(String[] args) {
    try {
        int x = 10 / 2;
    } catch (java.io.IOException e) {
        System.out.println("caught");
    }
}

try {
    double x = 1.0 / 0.0;
    System.out.println(x);
} catch (ArithmeticException e) {
    System.out.println("arithmetic");
}

public static void test() {
    try {
        throw new IllegalArgumentException("try");
    } finally {
        throw new NullPointerException("finally");
    }
}
public static void main(String[] args) {
    try {
        test();
    } catch (Exception e) {
        System.out.println(e.getMessage());
    }
}

try {
    throw new NullPointerException();
} catch (NullPointerException | ArithmeticException e) {
    e = new NullPointerException();
    System.out.println("caught");
}

try {
    throw new java.io.FileNotFoundException();
} catch (java.io.IOException e) {
    System.out.println("IO");
} catch (java.io.FileNotFoundException e) {
    System.out.println("FNF");
}

